package com.sathavahana.kalamkari.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="users")
public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String email; @Column(name="password_hash") private String passwordHash; @Column(name="first_name",nullable=false) private String firstName; @Column(name="last_name") private String lastName; private String phone; @Enumerated(EnumType.STRING) private Role role=Role.CUSTOMER; @Enumerated(EnumType.STRING) @Column(nullable=false) private Status status=Status.ACTIVE; @Column(name="created_at") private Instant createdAt=Instant.now(); public enum Role{CUSTOMER,ADMIN,SUPER_ADMIN,CATALOG_MANAGER,ORDER_MANAGER} public enum Status{ACTIVE,INACTIVE,BLOCKED,PENDING_VERIFICATION} public User(){} public Long getId(){return id;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getFirstName(){return firstName;} public void setFirstName(String v){firstName=v;} public String getLastName(){return lastName;} public void setLastName(String v){lastName=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String v){passwordHash=v;} public Role getRole(){return role;} public void setRole(Role v){role=v;} public Status getStatus(){return status;} public void setStatus(Status v){status=v;} }
